import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

class Solution {
    public static int findWinner(int n, int k) {
        // Create a queue with people numbered 0 to n-1
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            queue.offer(i);
        }

        // Continue until only one person remains
        while (queue.size() > 1) {
            // Count k-1 people and move them to the back
            for (int i = 0; i < k - 1; i++) {
                queue.offer(queue.poll());
            }
            // Eliminate the kth person
            queue.poll();
        }

        // Return the last remaining person
        return queue.peek();
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        int k = Integer.parseInt(scanner.nextLine());
        scanner.close();
        int res = findWinner(n, k);
        System.out.println(res);
    }
}
